Code:
```python
from heapq import heappop, heappush

def solve(n, edges, source, target):
    graph = [[] for _ in range(n)]
    for u, v, weight in edges:
        graph[u].append((v, weight))
        graph[v].append((u, weight))
    best = [float("inf")] * n
    best[source] = 0
    queue = [(0, 0, source)]
    while queue:
        total, largest, node = heappop(queue)
        if total != best[node]:
            continue
        if node == target:
            return largest
        for nxt, weight in graph[node]:
            new_total = total + weight
            if new_total < best[nxt]:
                best[nxt] = new_total
                heappush(queue, (new_total, max(largest, weight), nxt))
    return -1

