    graph = [[] for _ in range(n)]
    for u, v, weight in edges:
        graph[u].append((v, weight))
    best = [[float("inf")] * (max_edges + 1) for _ in range(n)]
    best[source][0] = 0
    queue = [(0, 0, source)]
    while queue:
        cost, used, node = heappop(queue)
        if cost != best[node][used]:
            continue
        if any(best[node][h] <= cost for h in range(used)):
            continue
        if node == target:
            return cost
        if used == max_edges:
            continue
        for nxt, weight in graph[node]:
            new_used = used + 1
            new_cost = cost + weight
            if new_cost < best[nxt][new_used]:
                best[nxt][new_used] = new_cost
                heappush(queue, (new_cost, new_used, nxt))
    return -1

```

